 html+=`<section class="card"><div class="card-heading"><span>${esc(t.roster)}</span><span>${w.roster.length}</span></div><p class="gm-note">${esc(t.rosterHelp)}</p>${w.roster.length?w.roster.map((n,i)=>npcRosterHTML(n,i,t,lang)).join(''):`<p class="gm-note">${esc(t.empty)}</p>`}${w.roster.length?button('clear',t.clear):''}</section></div>`;
