function encounterHTML(row,t,l){return `<div class="gm-match"><strong>${row[0]}–${row[1]} · ${esc(row[l==='ru'?3:4])}</strong><p>${esc(row[l==='ru'?5:6])}</p><button class="rule-source" data-action="book-page" data-page="${row[2]}">${esc(t.source)} ${row[2]} ↗</button></div>`}
function npcTemplateHTML(n,t,l){const armor=(l==='ru'?ARMOR_RU[n.armor.name]:null)||n.armor.name,skills=Object.entries(n.skillBases).map(([key,val])=>{let name=l==='ru'?(SKILLS_RU[key]||window.SKILL_LABELS?.[key]?.ru||key):key;let value=val===null?'?':typeof val==='object'?`${val.base} (${val.armored})`:val;return `${name}: ${value}`}).join(' · '),weapons=n.weapons.map(x=>`${l==='ru'?WEAPONS_RU[x.name]||x.name:x.name}: ${x.damage}`).join(' · '),notes=l==='ru'?SPECIAL_RU[n.id]:n.note;return `<article class="gm-card"><h3>${esc(n.name[l])}</h3><p>${esc(t.source)} ${n.page} · HP ${n.hp} · ${l==='ru'?'Тяжёлое ранение ниже':'Seriously Wounded below'} ${n.serious} · Death Save ${n.death} · ${esc(t.sp)} ${esc(armor)} ${n.armor.headSP}/${n.armor.bodySP}</p><div class="gm-statline">${Object.entries(n.stats).map(([k,v])=>`<span>${esc(k)} ${v}${n.effectiveStats?.[k]!==undefined?` (${n.effectiveStats[k]})`:''}</span>`).join('')}</div><details><summary>${esc(t.skills)} / ${esc(t.equipment)}</summary><p class="gm-note">${l==='ru'?'База навыка уже включает характеристику и применимые модификаторы; не прибавляйте STAT повторно. Скобки означают значение в броне.':'Skill Base already includes STAT and applicable modifiers; do not add STAT again. Parentheses show the armored value.'}</p><p>${esc(skills)}</p><p>${esc(weapons)}</p><p>${esc(l==='ru'?EQUIPMENT_RU[n.id]||n.equipment:n.equipment)}</p>${n.ability?`<p>${esc(n.ability.name)} · ${l==='ru'?'ранг':'rank'} ${n.ability.rank}</p>`:''}${n.programs?`<p>NET: ${esc(n.programs.join(', '))}</p>`:''}${notes?`<p class="gm-warning">${esc(notes)}</p>`:''}</details><div class="gm-actions">${button('add',t.add,`data-id="${esc(n.id)}"`)}<button class="rule-source" data-action="book-page" data-page="${n.page}">${esc(t.source)} ${n.page} ↗</button></div></article>`}
// Persistent NPC armor is optional for backwards compatibility. Unknown versions remain untouched.
const NPC_ARMOR_TEXT={ru:{title:'БРОНЯ И УРОН NPC',head:'SP головы',body:'SP тела',set:'Сохранить SP',damage:'Применить урон',raw:'Урон до брони',location:'Попадание',headLoc:'Голова',bodyLoc:'Тело',type:'Тип урона',standard:'Обычный',melee:'Оружие ближнего боя / Martial Arts',direct:'В обход брони',critical:'Критическая травма: +5 прямого урона',note:'Для Brawling выберите обычный тип: броня не делится пополам. Рассчитайте бросок урона и травму отдельно. Травмы, состояние при смерти и особые эффекты отслеживаются вручную.',invalid:'Проверьте HP, SP и параметры урона. Неизвестная версия брони сохраняется без изменений.',stale:'Данные, аккаунт или форма изменились. Повторите действие.',setConfirm:'Сохранить текущие SP головы и тела?',confirm:'Подтвердить урон'},en:{title:'NPC ARMOR & DAMAGE',head:'Head SP',body:'Body SP',set:'Save SP',damage:'Apply damage',raw:'Damage before armor',location:'Hit location',headLoc:'Head',bodyLoc:'Body',type:'Damage type',standard:'Standard',melee:'Melee weapons / Martial Arts',direct:'Bypasses armor',critical:'Critical injury: +5 direct damage',note:'For Brawling use Standard: armor is not halved. Roll damage and critical injury separately. Track injuries, death state and special effects manually.',invalid:'Check HP, SP and damage inputs. Unknown armor versions are preserved unchanged.',stale:'The data, account or form changed. Please retry.',setConfirm:'Save current head and body SP?',confirm:'Confirm damage'}};
function npcArmor(n,temp){const a=n.armorTrack;if(a===undefined)return {version:1,head:temp.armor.headSP,body:temp.armor.bodySP};if(!a||typeof a!=='object'||Array.isArray(a)||a.version!==1||!Number.isSafeInteger(a.head)||a.head<0||a.head>1000||!Number.isSafeInteger(a.body)||a.body<0||a.body>1000)return null;return a}
